import { createSlice } from '@reduxjs/toolkit';
import { Province } from '@src/domain/entities/address/province';
import { getDistrictListThunk, getProvinceListThunk, getWardListThunk } from './thunk';
import { District } from '@src/domain/entities/address/district';
interface AddressState {
    provinceList: Province[] | null;
    loading: boolean | null;
    error: string | null;
    districtList: District[] | null;
}
const initialState: AddressState = {
    provinceList: null,
    districtList: null,
    loading: true,
    error: null
};
const addressSlice = createSlice({
    name: 'address',
    initialState,
    reducers: {},
    extraReducers: (builder) => {
        builder
            .addCase(getProvinceListThunk.pending, (state) => {
                state.loading = true;
            })
            .addCase(getProvinceListThunk.fulfilled, (state, action) => {
                state.loading = false;
                state.provinceList = action.payload.data;
            })
            .addCase(getProvinceListThunk.rejected, (state, action) => {
                state.loading = false;
                // state.error = action.error.message;
            })
            .addCase(getDistrictListThunk.pending, (state) => {
                state.loading = true;
            })
            .addCase(getDistrictListThunk.fulfilled, (state, action) => {
                // state.loading = false;
                // state.districtList = action.payload.data;
            })
            .addCase(getDistrictListThunk.rejected, (state, action) => {
                state.loading = false;
                // state.error = action.error.message;
            })
            .addCase(getWardListThunk.pending, (state) => {
                state.loading = true;
            })
            .addCase(getWardListThunk.fulfilled, (state, action) => {
                state.loading = false;
                // state.districtList = action.payload.data;
            })
            .addCase(getWardListThunk.rejected, (state, action) => {
                state.loading = false;
                // state.error = action.error.message;
            })
    },
});
export default addressSlice;