import React, { FC, useEffect, useRef } from 'react';
import { View } from 'react-native';
import { BottomSheetManager, BottomSheet, BottomSheetRef, Text, GradientButton, Spacer, useTheme } from '@core/ui';
import useCSS from '@src/presentation/style';
import { useTranslation } from 'react-i18next';
import AnimatedLottieView from 'lottie-react-native';
import { RefundPinch } from '@src/assets/lottie';

interface Props {
    show: boolean;
    onClose?: () => void;
}

const BottomSheetLoanInfo: FC<Props> = ({ show = false, onClose }) => {
    const css = useCSS();
    const { theme } = useTheme();
    const bsRef = useRef<BottomSheetRef>(null);
    const { t } = useTranslation(['module_collateral']);

    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} onClose={onClose} enableContentPanningGesture={false} snapPoints={['80%']}>
                    <AnimatedLottieView loop autoPlay style={[{ width: theme.Scaling.ms(100) }, css.ratio_square]} source={RefundPinch} />
                    <Text style={[css.text_title_200, css.font_semibold, css.text_black, css.mt_base]}>{t('screen_accounts.tnc_title')}</Text>
                    <View style={[css.p_medium]}>
                        <View style={[css.row, css.mt_base]}>
                            <View style={[css.w_base, css.h_base, css.bg_red_600, css.rounded_full, css.shrink_0, css.mr_base, css.mt_base]} />
                            <View style={[css.flex_1]}>
                                <Text style={[css.text_subheadline, css.font_bold, css.text_black]}>{t('screen_accounts.tnc_header_1')}</Text>
                                <Text style={[css.text_subheadline, css.font_regular, css.text_black, css.mt_small]}>{t('screen_accounts.tnc_content_1')}</Text>
                            </View>
                        </View>
                        <View style={[css.row, css.mt_base]}>
                            <View style={[css.w_base, css.h_base, css.bg_red_600, css.rounded_full, css.shrink_0, css.mr_base, css.mt_base]} />
                            <View style={[css.flex_1]}>
                                <Text style={[css.text_subheadline, css.font_bold, css.text_black]}>{t('screen_accounts.tnc_header_2')}</Text>
                                <Text style={[css.text_subheadline, css.font_regular, css.text_black, css.mt_small]}>{t('screen_accounts.tnc_content_2')}</Text>
                            </View>
                        </View>
                    </View>
                    <Spacer height={16} />
                    <GradientButton title={t('screen_accounts.tnc_close')} gradientProps={{ type: 'primary' }} onPress={() => bsRef.current?.close()} />
                </BottomSheet>
            ),
        });
    };

    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);
    return null;
};

export default BottomSheetLoanInfo;
